// ===================== Smart Custom Dropdown Modals & Select Enhancer =====================
(function initSmartCustomDropdowns() {
  'use strict';

  // 1. Support for standalone Smart Dropdown Modals (.smart-dropdown-trigger & .smart-dropdown-modal)
  function initSmartDropdownModals() {
    const triggers = document.querySelectorAll('.smart-dropdown-trigger');
    triggers.forEach(trigger => {
      if (trigger.dataset.smartInit === '1') return;
      trigger.dataset.smartInit = '1';

      trigger.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        const targetModalId = this.getAttribute('data-modal');
        const modal = targetModalId ? document.getElementById(targetModalId) : this.nextElementSibling;
        if (!modal) return;

        // Close other open modals
        document.querySelectorAll('.smart-dropdown-modal, .custom-dropdown-modal.active').forEach(m => {
          if (m !== modal) {
            m.style.display = 'none';
            m.classList.remove('active');
          }
        });

        // Toggle modal visibility
        const isVisible = modal.style.display === 'block' || modal.classList.contains('active');
        if (isVisible) {
          modal.style.display = 'none';
          modal.classList.remove('active');
        } else {
          modal.style.display = 'block';
          modal.classList.add('active');

          // Auto-focus search input and reset filter
          const searchInput = modal.querySelector('.dropdown-search-input, .fet-ms-search-input');
          if (searchInput) {
            searchInput.value = '';
            modal.querySelectorAll('.dropdown-item, .fet-ms-item').forEach(item => {
              item.style.display = '';
            });
            setTimeout(() => searchInput.focus(), 50);
          }
        }
      });
    });

    // Real-time search filter for standalone modals
    document.querySelectorAll('.smart-dropdown-modal .dropdown-search-input, .smart-dropdown-modal .fet-ms-search-input').forEach(input => {
      if (input.dataset.searchInit === '1') return;
      input.dataset.searchInit = '1';

      const filterItems = () => {
        const filter = input.value.trim().toLowerCase();
        const modal = input.closest('.smart-dropdown-modal') || input.closest('.custom-dropdown-modal');
        if (!modal) return;
        const items = modal.querySelectorAll('.dropdown-item, .fet-ms-item');

        items.forEach(item => {
          const text = (item.textContent || '').trim().toLowerCase();
          item.style.display = text.includes(filter) ? '' : 'none';
        });
      };

      input.addEventListener('input', filterItems);
      input.addEventListener('keyup', filterItems);
    });

    // Selection handling and dynamic text updater on trigger button
    document.querySelectorAll('.smart-dropdown-modal').forEach(modal => {
      if (modal.dataset.modalInit === '1') return;
      modal.dataset.modalInit = '1';

      modal.addEventListener('click', function (e) {
        const item = e.target.closest('.dropdown-item, .fet-ms-item');
        if (!item) return;

        const value = item.getAttribute('data-value') || item.dataset.idx || item.textContent.trim();
        const text = (item.querySelector('span')?.textContent || item.textContent).trim();
        const modalId = this.getAttribute('id');

        const trigger = modalId
          ? document.querySelector(`.smart-dropdown-trigger[data-modal="${modalId}"]`)
          : this.previousElementSibling;

        if (trigger) {
          trigger.setAttribute('data-selected-value', value);
          const textSpan = trigger.querySelector('.trigger-text');
          if (textSpan) {
            textSpan.textContent = text;
          } else {
            trigger.textContent = text;
          }
          trigger.dispatchEvent(new Event('change', { bubbles: true }));
        }

        this.style.display = 'none';
        this.classList.remove('active');
      });
    });

    // Close on outside click
    document.addEventListener('click', function (e) {
      if (!e.target.closest('.smart-dropdown-modal') && !e.target.closest('.smart-dropdown-trigger')) {
        document.querySelectorAll('.smart-dropdown-modal').forEach(m => {
          m.style.display = 'none';
          m.classList.remove('active');
        });
      }
    });
  }

  // 2. Select Elements Enhancer (Multi-select and styled dropdowns)
  function enhanceSelect(select) {
    if (select.dataset.msEnhanced === '1') return;
    select.dataset.msEnhanced = '1';
    select.style.position = 'absolute';
    select.style.opacity = '0';
    select.style.pointerEvents = 'none';
    select.style.width = '1px';
    select.style.height = '1px';

    const wrap = document.createElement('div');
    wrap.className = 'custom-dropdown-container';
    wrap.style.position = 'relative';
    wrap.style.width = '100%';
    select.parentNode.insertBefore(wrap, select);
    wrap.appendChild(select);

    const trigger = document.createElement('button');
    trigger.type = 'button';
    trigger.className = 'teacher-select-trigger smart-dropdown-trigger';
    trigger.style.width = '100%';
    trigger.style.textAlign = 'start';
    trigger.style.display = 'flex';
    trigger.style.alignItems = 'center';
    trigger.style.justifyContent = 'space-between';
    
    const triggerTextSpan = document.createElement('span');
    triggerTextSpan.className = 'trigger-text';
    triggerTextSpan.textContent = select.getAttribute('data-placeholder') || 'اختر... ▾';
    trigger.appendChild(triggerTextSpan);
    wrap.appendChild(trigger);

    const panel = document.createElement('div');
    panel.className = 'custom-dropdown-modal smart-dropdown-modal fet-ms-panel';
    panel.innerHTML =
      (select.multiple
        ? '<div class="dropdown-header fet-ms-header"><span>تحديد الكل</span><input type="checkbox" class="fet-ms-all" /></div>'
        : '') +
      '<div class="dropdown-search-box fet-ms-search" style="padding:6px 8px;background:#f8fafc;border-bottom:1px solid #e2e8f0;">' +
      '<input type="text" class="dropdown-search-input fet-ms-search-input" placeholder="بحث سريع..." style="width:100%;padding:6px 10px;font-size:0.8rem;border:1px solid #cbd5e1;border-radius:6px;outline:none;" />' +
      '</div>' +
      '<div class="dropdown-list fet-ms-list" style="max-height:190px;overflow-y:auto;padding:4px;"></div>' +
      '<div class="dropdown-actions fet-ms-actions">' +
      '<button type="button" class="btn-cancel fet-ms-cancel">إلغاء</button>' +
      '<button type="button" class="btn-confirm fet-ms-ok">موافق</button></div>';
    wrap.appendChild(panel);

    const list = panel.querySelector('.fet-ms-list');
    const allCb = panel.querySelector('.fet-ms-all');
    const searchInput = panel.querySelector('.fet-ms-search-input');
    let snapshot = [];

    function refreshList() {
      list.innerHTML = '';
      if (searchInput) searchInput.value = '';
      Array.from(select.options).forEach((opt, idx) => {
        if (!opt.value && opt.disabled) return;
        const row = document.createElement('label');
        row.className = 'dropdown-item fet-ms-item';
        row.style.display = 'flex';
        row.style.alignItems = 'center';
        row.style.justifyContent = 'space-between';
        row.style.padding = '6px 8px';
        row.style.cursor = 'pointer';
        row.style.borderRadius = '4px';

        const span = document.createElement('span');
        span.textContent = opt.textContent;
        span.style.fontSize = '0.82rem';
        span.style.fontWeight = '600';

        const cb = document.createElement('input');
        cb.type = select.multiple ? 'checkbox' : 'radio';
        cb.name = select.multiple ? '' : ('radio_' + (select.name || Math.random().toString(36)));
        cb.checked = opt.selected;
        cb.dataset.idx = String(idx);

        if (!select.multiple) {
          row.addEventListener('click', (e) => {
            if (e.target !== cb) cb.checked = true;
            Array.from(select.options).forEach((o, i) => { o.selected = (i === idx); });
            select.dispatchEvent(new Event('change', { bubbles: true }));
            select.dispatchEvent(new Event('input', { bubbles: true }));
            updateTrigger();
            panel.classList.remove('active');
            panel.style.display = 'none';
          });
        }

        row.appendChild(span);
        row.appendChild(cb);
        list.appendChild(row);
      });
    }

    // Dynamic Text Updater on Trigger Button
    function updateTrigger() {
      const selected = Array.from(select.options).filter(o => o.selected && (o.value || !o.disabled));
      const placeholder = select.getAttribute('data-placeholder') || 'اختر... ▾';
      let displayText = '';

      if (!selected.length) {
        displayText = placeholder;
      } else if (selected.length === 1) {
        displayText = selected[0].textContent.trim();
      } else if (selected.length <= 3) {
        displayText = selected.map(o => o.textContent.trim()).join('، ');
      } else {
        displayText = selected.slice(0, 2).map(o => o.textContent.trim()).join('، ') + ` (+${selected.length - 2})`;
      }

      if (triggerTextSpan) {
        triggerTextSpan.textContent = displayText;
      } else {
        trigger.textContent = displayText;
      }
    }

    // Real-Time Search Filter
    if (searchInput) {
      const runFilter = () => {
        const q = searchInput.value.toLowerCase().trim();
        list.querySelectorAll('.fet-ms-item').forEach(item => {
          const txt = item.querySelector('span')?.textContent.toLowerCase() || '';
          item.style.display = txt.includes(q) ? 'flex' : 'none';
        });
      };
      searchInput.addEventListener('input', runFilter);
      searchInput.addEventListener('keyup', runFilter);
    }

    trigger.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      document.querySelectorAll('.custom-dropdown-modal.active, .smart-dropdown-modal.active').forEach(m => {
        if (m !== panel) {
          m.classList.remove('active');
          m.style.display = 'none';
        }
      });
      snapshot = Array.from(select.options).map(o => o.selected);
      refreshList();
      panel.classList.toggle('active');
      panel.style.display = panel.classList.contains('active') ? 'block' : 'none';
      if (panel.classList.contains('active') && searchInput) {
        setTimeout(() => searchInput.focus(), 50);
      }
    });

    if (allCb) {
      allCb.addEventListener('change', () => {
        list.querySelectorAll('input[type=checkbox]').forEach(cb => {
          const parent = cb.closest('.fet-ms-item');
          if (!parent || parent.style.display !== 'none') {
            cb.checked = allCb.checked;
          }
        });
      });
    }

    panel.querySelector('.fet-ms-ok').addEventListener('click', (e) => {
      e.preventDefault();
      list.querySelectorAll('input[data-idx]').forEach(cb => {
        const i = Number(cb.dataset.idx);
        if (select.options[i]) select.options[i].selected = cb.checked;
      });
      select.dispatchEvent(new Event('change', { bubbles: true }));
      select.dispatchEvent(new Event('input', { bubbles: true }));
      updateTrigger();
      panel.classList.remove('active');
      panel.style.display = 'none';
    });

    panel.querySelector('.fet-ms-cancel').addEventListener('click', (e) => {
      e.preventDefault();
      select.options.forEach((o, i) => { o.selected = !!snapshot[i]; });
      panel.classList.remove('active');
      panel.style.display = 'none';
    });

    document.addEventListener('click', (e) => {
      if (!wrap.contains(e.target)) {
        panel.classList.remove('active');
        panel.style.display = 'none';
      }
    });

    select.addEventListener('change', updateTrigger);
    updateTrigger();
  }

  function scanSelects() {
    initSmartDropdownModals();
    document.querySelectorAll('select[multiple], select.custom-dropdown-select, select.teacher-select').forEach(enhanceSelect);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', scanSelects);
  } else {
    scanSelects();
  }
  const observer = new MutationObserver(() => scanSelects());
  observer.observe(document.documentElement, { childList: true, subtree: true });
})();
